"use client";
import { useCallback, useEffect, useState } from "react";
import { Button } from "@/components/ui/button";
import { ErrorNote } from "@/components/ui/states";
import { api } from "@/lib/client-api";
import { formatDate } from "@/lib/labels";

interface ExportRow {
  id: string;
  format: string;
  filename: string;
  created_at: string;
}

/** Report exports (PD-18 A: JSON and Markdown), generated by a job then downloaded. */
export function ExportPanel({
  workspaceId,
  analysisId,
  canEdit,
}: {
  workspaceId: string;
  analysisId: string;
  canEdit: boolean;
}) {
  const base = `/workspaces/${workspaceId}/analyses/${analysisId}/exports`;
  const [rows, setRows] = useState<ExportRow[]>([]);
  const [pending, setPending] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    try {
      setRows((await api<{ data: ExportRow[] }>(base)).data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Erreur");
    }
  }, [base]);
  useEffect(() => {
    void load();
  }, [load]);

  async function request(format: "json" | "markdown") {
    setError(null);
    try {
      const res = await api<{ data: { status_url: string } }>(base, {
        method: "POST",
        body: { format },
        idempotencyKey: crypto.randomUUID(),
      });
      setPending(res.data.status_url.replace(/^\/api\/v1/, ""));
    } catch (err) {
      setError(err instanceof Error ? err.message : "Erreur");
    }
  }

  useEffect(() => {
    if (!pending) return;
    const t = setInterval(async () => {
      try {
        const job = await api<{ data: { state: string } }>(pending);
        if (
          ["completed", "partial", "failed", "cancelled", "dead_letter"].includes(job.data.state)
        ) {
          clearInterval(t);
          setPending(null);
          if (job.data.state !== "completed") setError("L’export a échoué.");
          await load();
        }
      } catch (err) {
        clearInterval(t);
        setPending(null);
        setError(err instanceof Error ? err.message : "Erreur");
      }
    }, 1500);
    return () => clearInterval(t);
  }, [pending, load]);

  return (
    <div className="space-y-2" aria-live="polite">
      {canEdit ? (
        <div className="flex flex-wrap gap-2">
          <Button size="sm" disabled={pending !== null} onClick={() => request("markdown")}>
            Exporter en Markdown
          </Button>
          <Button size="sm" disabled={pending !== null} onClick={() => request("json")}>
            Exporter en JSON
          </Button>
          {pending ? <span className="text-sm text-muted">Export en cours…</span> : null}
        </div>
      ) : null}
      {rows.length > 0 ? (
        <ul className="space-y-1 text-sm" aria-label="Exports">
          {rows.map((r) => (
            <li key={r.id}>
              <a className="text-accent underline" href={`/api/v1${base}/${r.id}`} download>
                {r.filename}
              </a>{" "}
              <span className="text-xs text-muted">{formatDate(r.created_at)}</span>
            </li>
          ))}
        </ul>
      ) : (
        <p className="text-sm text-muted">Aucun export.</p>
      )}
      {error ? <ErrorNote>{error}</ErrorNote> : null}
    </div>
  );
}
